import { useState, useEffect } from "react";
import { BrowserRouter, Routes, Route } from "react-router-dom";

import NavBar from "./components/NavBar";
import Home from "./pages/Home";
import About from "./pages/About";

const chaiEntries = "chai-entries";

function App() {
  const [entries, setEntries] = useState([]);

  // load once
  useEffect(() => {
    const saved = localStorage.getItem(chaiEntries);
    if (saved) setEntries(JSON.parse(saved));
  }, []);

  // save whenever entries change
  useEffect(() => {
    localStorage.setItem(chaiEntries, JSON.stringify(entries));
  }, [entries]);

  function addEntry(entry) {
    setEntries(prev => [entry, ...prev]);
  }

  function deleteEntry(id) {
    setEntries(prev => prev.filter(e => e.id !== id));
  }

  return (
    <BrowserRouter>
      <NavBar />
      <Routes>
        <Route path="/" element={
          <Home entries={entries} onAdd={addEntry} onDelete={deleteEntry} />
        } />
        <Route path="/about" element={<About />} />
      </Routes>
    </BrowserRouter>
  );
}

export default App;
